<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ubah Pengguna — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:linear-gradient(135deg,#f4f7fb,#e8eef7)}.wrap{max-width:710px;margin:auto}.back{display:inline-block;padding:10px 13px;background:#fff9;border:1px solid #fff;border-radius:10px;color:#23395d;text-decoration:none;font-size:13px;font-weight:800}.hero{margin:18px 0;padding:27px 29px;border-radius:21px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff}.hero h1{margin:0 0 6px;font-size:26px}.hero p{margin:0;color:#e7effa}.box{padding:24px;background:#fffd;border:1px solid #fff;border-radius:18px;box-shadow:0 14px 30px #23395d12}.field{display:grid;gap:7px;margin:14px 0}.field label{font-size:11px;font-weight:800;color:#475569;letter-spacing:.4px}input{padding:11px;border:1px solid #cbd5e1;border-radius:10px;font:inherit;outline:0}input:focus{border-color:#365d92;box-shadow:0 0 0 4px #a0b4d143}.button{border:0;border-radius:10px;padding:12px 17px;background:#23395d;color:#fff;font:800 14px Inter;cursor:pointer}.error{color:#b91c1c;font-size:13px}</style></head><body><main class="wrap"><a class="back" href="{{ route('admin.users') }}">← Manajemen Pengguna</a><section class="hero"><h1>Ubah Akun Pengguna</h1><p>Perbarui informasi {{ $user->name }} dengan aman.</p></section><section class="box">@php($identifier=$user->role==='student'?'nisn':($user->role==='teacher'?'nip':'username'))<form method="post" action="{{ route('admin.users.update',$user) }}">@csrf @method('PUT')<div class="field"><label>NAMA LENGKAP</label><input name="name" value="{{ old('name',$user->name) }}" required></div><div class="field"><label>{{ strtoupper($identifier) }}</label><input name="{{ $identifier }}" value="{{ old($identifier,$user->{$identifier}) }}" required></div>@if($user->role==='student')<div class="field"><label>KELAS SISWA</label><input name="class_name" value="{{ old('class_name',$user->class_name) }}"></div>@elseif($user->role==='teacher')<div class="field"><label>MAPEL YANG DIAMPU</label><input name="teaching_subject" value="{{ old('teaching_subject',$user->teaching_subject) }}" required></div><div class="field"><label>KELAS YANG DIAMPU</label><input name="teaching_class" value="{{ old('teaching_class',$user->teaching_class) }}" required></div>@endif<div class="field"><label>PASSWORD BARU</label><input type="password" name="password" placeholder="Kosongkan jika tidak ingin diubah"></div><div class="field"><label>KONFIRMASI PASSWORD BARU</label><input type="password" name="password_confirmation"></div>@foreach($errors->all() as $error)<p class="error">{{ $error }}</p>@endforeach<button class="button">Simpan Perubahan ✦</button></form></section></main></body></html>
